import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"[Generalità sui numeri naturali]","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/b_aritmetica-e-numeri/ba/baa.md","filePath":"lezioni/b_aritmetica-e-numeri/ba/baa.md"}`),a={name:`lezioni/b_aritmetica-e-numeri/ba/baa.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 class="text-red-darken-1" id="generalita-sui-numeri-naturali" tabindex="-1">[Generalità sui numeri naturali] <a class="header-anchor" href="#generalita-sui-numeri-naturali" aria-label="Permalink to “[Generalità sui numeri naturali]”">​</a></h1><p>I numeri naturali sono, storicamente, la base di tutta la matematica: sembra (dalle tracce lasciate su un osso di lupo) che fossero noti già <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>70.000</mn></mrow><annotation encoding="application/x-tex">70.000</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">70.000</span></span></span></span> anni fa.</p><p>Sono stati considerati degli oggetti iniziali finché, agli inizi del <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>900</mn></mrow><annotation encoding="application/x-tex">900</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">900</span></span></span></span>, si sentì il bisogno di farli derivare da concetti più elementari (quali il concetto di cardinale in teoria degli insiemi) ed anche di sottoporli ad una rigorosa assiomatica (assiomi di Peano);</p><blockquote><p>Qui mi limito ad una generica introduzione adatta ad un primo anno del biennio delle scuole medie superiori</p></blockquote><p>Al solito ci sono due teorie: quella dei matematici che credono che i numeri naturali esistano effettivamente e quelli che credono che i numeri siano una costruzione del nostro cervello. In entrambi i casi i risultati che otterremo saranno gli stessi.</p>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};